docker exec clearcaseiq-prod-api sh -lc 'cat > /tmp/dr.cjs <<"EOF"
const { prisma } = require("/app/src/lib/prisma");
const mask = (e) => (e ? "***@" + String(e).split("@")[1] : "NONE");
(async () => {
  const reqs = await prisma.documentRequest.findMany({ where: { targetType: "plaintiff" }, orderBy: { createdAt: "desc" }, take: 6, select: { id: true, leadId: true, attorneyId: true, requestedDocs: true, status: true, createdAt: true } });
  for (const r of reqs) {
    const lead = await prisma.leadSubmission.findUnique({ where: { id: r.leadId }, select: { assessment: { select: { userId: true, user: { select: { email: true } } } } } });
    const notes = await prisma.notification.findMany({ where: { metadata: { contains: r.id } }, select: { type: true, status: true, recipient: true, metadata: true, createdAt: true } });
    const n = notes.map((x) => { let m = {}; try { m = JSON.parse(x.metadata || "{}"); } catch {} return x.type + ":" + x.status + " to " + mask(x.recipient) + (m.failureReason ? " reason=" + m.failureReason : ""); });
    console.log([r.createdAt.toISOString(), "req=" + r.id, "lead=" + r.leadId, "docs=" + r.requestedDocs, "status=" + r.status, "clientUser=" + (lead && lead.assessment && lead.assessment.userId ? "yes" : "NO"), "clientEmail=" + mask(lead && lead.assessment && lead.assessment.user && lead.assessment.user.email), "emails=[" + (n.join("; ") || "NONE") + "]"].join(" | "));
  }
  process.exit(0);
})().catch(e => { console.error("ERR", e.message); process.exit(1); });
EOF
cd /app && node /tmp/dr.cjs; rm -f /tmp/dr.cjs'
